import { sql } from 'drizzle-orm';
import type { JobPayloads } from '../shared/queue/index.js';
import type { JobContext, JobOutcome } from './context.js';
import { trackedRun } from './runs.js';

/**
 * Analytics.
 *
 *   analytics-events  the API enqueues shopper actions in batches (it never
 *                     writes them inside a request). Each event carries an id
 *                     generated by the producer, and the table's key is
 *                     (id, occurred_at), so a redelivered batch inserts
 *                     nothing twice.
 *   analytics-rollup  recomputes business_daily_metrics for today and
 *                     yesterday FROM the events (plus offer redemptions): a
 *                     full recompute of a day is idempotent — run it twice,
 *                     get the same numbers. Businesses with no events that
 *                     day are left as they are.
 */

const TYPES = new Set([
  'IMPRESSION',
  'BUSINESS_VIEW',
  'OFFERING_VIEW',
  'COMPARISON_VIEW',
  'SEARCH',
  'DIRECTIONS',
  'CALL',
  'FAVORITE',
  'OFFER_CLAIM',
  'OFFER_REDEEM',
  'REVIEW',
  'SUBMISSION',
  'APPROVAL',
  'REJECTION',
]);
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const uuidOrNull = (v: unknown) => (typeof v === 'string' && UUID.test(v) ? v : null);

export async function analyticsEvents(ctx: JobContext, payload: JobPayloads['analytics-events']): Promise<JobOutcome> {
  const now = Date.now();
  const rows = (payload.events ?? [])
    .filter((e) => TYPES.has(e.type) && uuidOrNull(e.id))
    .map((e) => {
      const at = new Date(e.at);
      // A timestamp from the future or older than 2 days is clamped to now: a
      // bad clock must not create rows in partitions that don't exist.
      const t = Number.isNaN(at.getTime()) || at.getTime() > now + 60_000 || at.getTime() < now - 2 * 86_400_000 ? new Date(now) : at;
      return sql`(${e.id}::uuid, ${e.type}::analytics_event, ${uuidOrNull(e.businessId)}::uuid, ${uuidOrNull(e.offeringId)}::uuid, ${uuidOrNull(e.areaId)}::uuid, ${typeof e.sessionHash === 'string' ? e.sessionHash.slice(0, 64) : null}, ${JSON.stringify(e.properties ?? {})}::jsonb, ${t.toISOString()}::timestamptz)`;
    });
  if (!rows.length) return { status: 'skipped', detail: 'no valid events' };
  const inserted = (await ctx.db.execute(sql`
    INSERT INTO analytics_events (id, event_type, business_id, offering_id, area_id, session_hash, properties, occurred_at)
    VALUES ${sql.join(rows, sql`, `)}
    ON CONFLICT DO NOTHING
    RETURNING id`)) as unknown as unknown[];
  return {
    status: 'done',
    received: payload.events.length,
    inserted: inserted.length,
  };
}

/**
 * Batch statements get their own time budget: at 100k businesses a day's
 * rollup ran past the 10 s OLTP statement timeout, failed, and its retries
 * kept the database busy (measured, Phase 19).
 */
const ROLLUP_STATEMENT_TIMEOUT = '120s';

async function rollupDay(ctx: JobContext, day: string) {
  return ctx.db.transaction(async (tx) => {
    await tx.execute(sql`SET LOCAL statement_timeout = ${sql.raw(`'${ROLLUP_STATEMENT_TIMEOUT}'`)}`);
    await tx.execute(sql`SELECT pg_advisory_xact_lock(hashtext('rollup-day:' || ${day}))`);
    const r = (await tx.execute(sql`
    WITH e AS (
      SELECT business_id,
             coalesce(sum(coalesce((properties->>'n')::int, 1)) FILTER (WHERE event_type = 'IMPRESSION'), 0)::int AS impressions,
             count(*) FILTER (WHERE event_type = 'BUSINESS_VIEW')::int AS views,
             count(*) FILTER (WHERE event_type = 'OFFERING_VIEW')::int AS offering_views,
             count(*) FILTER (WHERE event_type = 'COMPARISON_VIEW')::int AS comparison_appearances,
             count(*) FILTER (WHERE event_type = 'DIRECTIONS')::int AS directions,
             count(*) FILTER (WHERE event_type = 'CALL')::int AS calls
      FROM analytics_events
      WHERE occurred_at >= ${day}::date AND occurred_at < ${day}::date + 1 AND business_id IS NOT NULL
      GROUP BY business_id
    ),
    v AS (
      SELECT business_id, count(*)::int AS visits FROM offer_claims
      WHERE redeemed_at >= ${day}::date AND redeemed_at < ${day}::date + 1 GROUP BY business_id
    ),
    j AS (
      SELECT coalesce(e.business_id, v.business_id) AS business_id, e.impressions, e.views, e.offering_views, e.comparison_appearances, e.directions, e.calls, v.visits
      FROM e FULL JOIN v ON v.business_id = e.business_id
    )
    INSERT INTO business_daily_metrics (business_id, date, impressions, views, offering_views, comparison_appearances, directions, calls, confirmed_visits, updated_at)
    SELECT j.business_id, ${day}::date, coalesce(impressions, 0), coalesce(views, 0), coalesce(offering_views, 0), coalesce(comparison_appearances, 0), coalesce(directions, 0), coalesce(calls, 0), coalesce(visits, 0), now()
    FROM j JOIN businesses b ON b.id = j.business_id
    ON CONFLICT (business_id, date) DO UPDATE SET
      impressions = EXCLUDED.impressions, views = EXCLUDED.views, offering_views = EXCLUDED.offering_views,
      comparison_appearances = EXCLUDED.comparison_appearances, directions = EXCLUDED.directions, calls = EXCLUDED.calls,
      confirmed_visits = EXCLUDED.confirmed_visits, updated_at = now()
    -- Only rows whose numbers moved: a settled day (yesterday, after midnight)
    -- is re-read but not rewritten every ten minutes.
    WHERE (business_daily_metrics.impressions, business_daily_metrics.views, business_daily_metrics.offering_views,
           business_daily_metrics.comparison_appearances, business_daily_metrics.directions, business_daily_metrics.calls,
           business_daily_metrics.confirmed_visits)
      IS DISTINCT FROM (EXCLUDED.impressions, EXCLUDED.views, EXCLUDED.offering_views, EXCLUDED.comparison_appearances,
                        EXCLUDED.directions, EXCLUDED.calls, EXCLUDED.confirmed_visits)
    RETURNING business_id`)) as unknown as unknown[];
    return r.length;
  });
}

/** search_term_daily for one day, recomputed from SEARCH events (delete + insert in one transaction: idempotent). */
async function rollupSearches(ctx: JobContext, day: string) {
  return ctx.db.transaction(async (tx) => {
    await tx.execute(sql`SET LOCAL statement_timeout = ${sql.raw(`'${ROLLUP_STATEMENT_TIMEOUT}'`)}`);
    // One rollup per day at a time, whatever Redis says (the lock there can lapse):
    // concurrent runs would otherwise both delete, then both insert.
    await tx.execute(sql`SELECT pg_advisory_xact_lock(hashtext('rollup-searches:' || ${day}))`);
    await tx.execute(sql`DELETE FROM search_term_daily WHERE date = ${day}::date`);
    const r = (await tx.execute(sql`
      INSERT INTO search_term_daily (date, query, searches, visitors)
      SELECT ${day}::date, left(coalesce(properties->>'query', ''), 120), count(*)::int, count(DISTINCT session_hash)::int
      FROM analytics_events
      WHERE event_type = 'SEARCH' AND occurred_at >= ${day}::date AND occurred_at < ${day}::date + 1
      GROUP BY 2
      ON CONFLICT (date, query) DO UPDATE SET searches = EXCLUDED.searches, visitors = EXCLUDED.visitors
      RETURNING query`)) as unknown as unknown[];
    return r.length;
  });
}

export async function analyticsRollup(ctx: JobContext, payload: JobPayloads['analytics-rollup']): Promise<JobOutcome> {
  return trackedRun(ctx, 'analytics-rollup', 10 * 60_000, async () => {
    const days = payload.date && /^\d{4}-\d{2}-\d{2}$/.test(payload.date) ? [payload.date] : [new Date(Date.now() - 86_400_000), new Date()].map((d) => d.toISOString().slice(0, 10));
    const perDay: Record<string, number> = {};
    const terms: Record<string, number> = {};
    for (const d of days) {
      perDay[d] = await rollupDay(ctx, d);
      terms[d] = await rollupSearches(ctx, d);
    }
    return { status: 'done', businessesUpdated: perDay, searchTerms: terms };
  });
}
